using Muyu.Core;
using System.Text;
using System.Text.Json;
public static class CompletionTests
{
    public static async Task Run(string root,Action<bool,string> check)
    {
        var wav=Path.Combine(root,"reference-16.wav");var info=NativeAudio.Probe(wav);Track TrackOf(string path){var i=NativeAudio.Probe(path);return new(Track.Identity(path),path,Path.GetFileNameWithoutExtension(path),"Artist","Album",i.SampleRate,i.Bits,i.Channels,i.Frames,Encoding:i.Encoding);}
        var track=TrackOf(wav);var a=new QueueItem(Guid.NewGuid(),track);var b=new QueueItem(Guid.NewGuid(),track);var c=new QueueItem(Guid.NewGuid(),track);var d=new QueueItem(Guid.NewGuid(),track);var run=new PlaybackRun([a,b]);
        check(run.At(track.Frames-1).ItemId==a.ItemId&&run.At(track.Frames).ItemId==b.ItemId,"Cross-file output clock changes item exactly at sample boundary");
        check(run.SeekFrame(b.ItemId,12)==track.Frames+12,"Cross-file seek uses cumulative sample offset");
        using(var source=new NativeSource(run,new())){var pcm=new byte[16];source.Seek(track.Frames-1);check(source.Read(pcm,2,true)==2,"Cross-file ring reads across physical boundary");var last=new byte[4];var first=new byte[4];NativeAudio.muyu_read_pcm(wav,track.Frames-1,1,last,4);NativeAudio.muyu_read_pcm(wav,0,1,first,4);check(pcm.Take(8).SequenceEqual(last.Concat(first)),"Cross-file boundary has no dropped, duplicated or inserted samples");}
        using(var source=new NativeSource(new([a]),new(TargetRate:48000,TargetBits:24,GainDb:-6))){check(source.Format is {SampleRate:48000,Bits:24,ContainerBits:32},"Explicit native processing applies requested rate and valid bits");var pcm=new byte[4096*8];long frames=0;while(frames<source.Format.Frames){int count=(int)Math.Min(4096,source.Format.Frames-frames);frames+=source.Read(pcm,count,true);}check(frames==48000,"High quality resampler drains exact target duration");}
        using(var source=new NativeSource(new([a]),new(TargetChannels:1))){check(source.Format.Channels==1,"Explicit downmix changes channel count");}
        var fingerprint=LocalFileIdentity.Capture(wav);var evidence=new Dictionary<string,SourceFingerprint>{[track.Id]=fingerprint};
        using(var source=new NativeSource(run,new(),evidence)){check(source.Format.ContainerBits==32,"Verified playback uses canonical lossless PCM container");source.Seek(track.Frames-1);var actual=new byte[16];source.Read(actual,2,true);var original=new byte[4];NativeAudio.muyu_read_pcm(wav,track.Frames-1,1,original,4);check(actual.Take(8).SequenceEqual(new byte[]{0,0,original[0],original[1],0,0,original[2],original[3]}),"Canonical container only adds zero padding");bool locked=false;try{using var modifying=new FileStream(wav,FileMode.Open,FileAccess.Write,FileShare.ReadWrite);}catch(IOException){locked=true;}check(locked,"Verified audio remains protected from replacement while decoded");}
        bool rejected=false;try{using var source=new NativeSource(new([a]),new(),new Dictionary<string,SourceFingerprint>{[track.Id]=fingerprint with{Sha256=new string('0',64)}});}catch(IOException){rejected=true;}check(rejected,"Native playback rejects changed full source digest before reading samples");
        var missing=track with{Id="missing-tail",Path=Path.Combine(root,"missing-tail.wav")};var lazyEntries=Enumerable.Range(0,50).Select(_=>new QueueItem(Guid.NewGuid(),track)).Append(new(Guid.NewGuid(),missing)).ToArray();var lazyEvidence=new Dictionary<string,SourceFingerprint>(evidence){[missing.Id]=fingerprint};using(var source=new NativeSource(new(lazyEntries),new(),lazyEvidence)){var sample=new byte[8];check(source.Read(sample,1,true)==1,"Long queue begins without opening every later physical file");}
        var completed=new PlaybackSession(1,1,[a,b],null,0,CompletedItems:[a.ItemId,b.ItemId]);check(completed.Validate().CurrentIndex==-1,"Completed queue history can persist without an active current item");rejected=false;try{(completed with{CompletedItems=[Guid.NewGuid()]}).Validate();}catch(FormatException){rejected=true;}check(rejected,"Session rejects completed IDs outside its queue");
        var moved=QueueEditing.MovePending([a,b,c,d],0,new HashSet<Guid>{b.ItemId,d.ItemId},4);check(moved.Select(i=>i.ItemId).SequenceEqual(new[]{a.ItemId,c.ItemId,b.ItemId,d.ItemId}),"Queue batch move preserves selection relative order");
        var removed=QueueEditing.RemovePending([a,b,c,d],1,new HashSet<Guid>{a.ItemId,b.ItemId,c.ItemId});check(removed.Select(i=>i.ItemId).SequenceEqual(new[]{a.ItemId,b.ItemId,d.ItemId}),"Queue batch removal protects history and current entry");
        var undo=new QueueUndo(4,[a,b,c,d],a.ItemId,[]);check(QueueEditing.Restore([a,d],0,4,undo,new HashSet<Guid>{b.ItemId}).Select(i=>i.ItemId).SequenceEqual(new[]{a.ItemId,c.ItemId,d.ItemId}),"Queue undo never restores already passed items");
        bool conflict=false;try{QueueEditing.Restore([a,d],0,5,undo,new HashSet<Guid>());}catch(InvalidOperationException){conflict=true;}check(conflict,"Queue structural revision rejects stale undo");
        var meta=new TrackMetadata(["A","B"],["Various"],["Jazz"],2026,2,2,3,10,-6,-4,.9,.95);var tagged=track with{Metadata=meta};check(JsonSerializer.Deserialize<Track>(JsonSerializer.Serialize(tagged))==tagged,"Metadata arrays retain value equality after persistence");
        string dbPath=Path.Combine(root,"complete-"+Guid.NewGuid().ToString("N"));var store=new LibraryStore(dbPath);store.AddBatch([tagged]);check(store.ReadAll()[0].Metadata==meta&&store.ReadAll()[0].AlbumArtist=="Various","Album artist, disc, genre and year persist in library");store.RecordPlay(track.Id);check(store.Usage()[track.Id].Plays==1&&store.LibraryRevision>=2,"Play count and library revision update together");
        var now=DateTimeOffset.Now;var usage=new Dictionary<string,TrackUsage>{[track.Id]=new(now.AddDays(-1),null,0)};var smart=new SmartPlaylist(Guid.NewGuid(),"Jazz HD",1,true,[new(SmartField.Genre,SmartOperator.Contains,"jazz"),new(SmartField.LastPlayed,SmartOperator.Never,"")]);check(smart.Evaluate([tagged],new HashSet<string>(),usage,now).Count==1,"Smart rules combine genre and never played");
        check((smart with{MatchAll=false,Rules=[new(SmartField.Favorite,SmartOperator.Equals,"true"),new(SmartField.SampleRate,SmartOperator.Greater,"40000")]}).Evaluate([tagged],new HashSet<string>(),usage,now).Count==1,"Smart any-rule semantics");
        bool invalid=false;try{(smart with{Rules=[new(SmartField.SampleRate,SmartOperator.Contains,"NaN")]}).Validate();}catch(FormatException){invalid=true;}check(invalid,"Smart invalid field operator rejected");
        var preview=new SmartPreview(smart.Id,smart.Revision,3,[tagged]);invalid=false;try{preview.ValidateCurrent(smart,4);}catch(InvalidOperationException){invalid=true;}check(invalid,"Smart preview rejects changed library revision");
        string m3u=Path.Combine(root,"import-complete.m3u8");File.WriteAllText(m3u,"#EXTM3U\nreference-16.wav\nreference-16.wav\nhttps://example.invalid/audio.flac\n",new UTF8Encoding(false));var imported=PlaylistExchange.Import(m3u,NativeAudio.Probe);check(imported.Tracks.Count==2&&imported.Warnings.Count==1,"M3U import preserves duplicates and rejects network URLs");
        string exchange=Path.Combine(root,"exchange.muyu-playlist");File.WriteAllText(exchange,PlaylistExchange.Export("test",[track with{StartFrame=100,EndFrame=200},track]));var roundtrip=PlaylistExchange.Import(exchange,NativeAudio.Probe);check(roundtrip.Tracks.Count==2&&roundtrip.Tracks[0].StartFrame==100&&roundtrip.Tracks[0].EndFrame==200,"Muyu exchange preserves physical source, ranges and order");
        File.WriteAllText(exchange,"{\"Version\":999,\"Name\":\"test\",\"Entries\":[]}");invalid=false;try{PlaylistExchange.Import(exchange,NativeAudio.Probe);}catch(FormatException){invalid=true;}check(invalid,"Unknown Muyu playlist version rejected");
        var words=LrcParser.Parse("[00:01.00]<00:01.00>Hello <00:01.50>world<00:02.00>\n[00:03.00]next");check(words.Lines[0].Text=="Hello world"&&words.Lines[0].Words?.Count==2,"Enhanced LRC preserves text and word timing");check(words.Lines[0].Words![1] is {Start:6,Length:5,Time:1.5},"Enhanced LRC word character range stays exact");
        string cue=Path.Combine(root,"pregap-complete.cue");File.WriteAllText(cue,"FILE \"reference-16.wav\" WAVE\nTRACK 01 AUDIO\nINDEX 01 00:00:10\nTRACK 02 AUDIO\nINDEX 00 00:00:30\nINDEX 01 00:00:40");var cues=CueParser.Load(cue,NativeAudio.Probe,pregapToNext:true,includeHidden:true);check(cues.Count==3&&cues[0].Title.Contains("隐藏")&&cues[1].EndFrame==17640&&cues[2].StartFrame==17640,"CUE hidden first audio and INDEX00 next-track policy");
        string cueText=File.ReadAllText(cue);check(CueParser.Load(wav,NativeAudio.Probe,embeddedText:cueText,embeddedAudioPath:wav).All(t=>t.Path==wav&&t.CuePath==wav),"Embedded CUE binds only its physical audio source");
        var settings=new AudioSettings(Device:"one",TargetRate:48000,GainDb:-6);settings.Validate();var auth=new AudioAuthorization(Guid.NewGuid(),"one","fingerprint",44100,16,2,settings.StrategyHash,now);check(auth.Matches(settings,track,"fingerprint")&&!auth.Matches(settings with{Device="two"},track,"fingerprint")&&!auth.Matches(settings,track,"changed"),"Conversion authorization is bound to device and capability fingerprint");check(!auth.Matches(settings with{GainDb=-3},track,"fingerprint")&&!auth.Matches(settings,track with{Bits=24},"fingerprint"),"Conversion authorization cannot cover new processing or source condition");
        invalid=false;try{new AudioSettings(Backend:AudioBackend.WasapiShared,Dsd:DsdMode.DoP).Validate();}catch(FormatException){invalid=true;}check(invalid,"DoP rejects shared mixing");invalid=false;try{new AudioSettings(GainDb:-6,Dsd:DsdMode.DoP).Validate();}catch(FormatException){invalid=true;}check(invalid,"DoP rejects software processing");
        var rg=new AudioSettings(ReplayGain:ReplayGainMode.Track,GainDb:12);check(Math.Abs(rg.EffectiveGain(tagged)-(-20*Math.Log10(.9)))<.00001,"ReplayGain peak protection includes user preamp");
        string dsf=Path.Combine(root,"raw-dsd-complete.dsf");using(var output=new BinaryWriter(File.Create(dsf))){const int dataBytes=16384;output.Write("DSD "u8);output.Write(28L);output.Write(92L+dataBytes);output.Write(0L);output.Write("fmt "u8);output.Write(52L);foreach(int n in new[]{1,0,2,2,2822400,1})output.Write(n);output.Write(65536L);output.Write(4096);output.Write(0);output.Write("data"u8);output.Write(12L+dataBytes);for(int block=0;block<2;block++)for(int channel=0;channel<2;channel++)for(int i=0;i<4096;i++)output.Write((byte)(channel==0?i:~i));}
        var dsdTrack=TrackOf(dsf);check(dsdTrack.SampleRate==352800&&dsdTrack.Frames==8192,"DSF PCM decode reports exact source duration");using(var source=new NativeSource(new([new(Guid.NewGuid(),dsdTrack)]),new(Dsd:DsdMode.DoP))){check(source.Format is{SampleRate:176400,Bits:24,ContainerBits:24,Frames:4096},"DSD64 DoP produces 24-bit 176.4 kHz framing");source.Seek(7);var frame=new byte[12];source.Read(frame,2,true);check(frame.Take(6).SequenceEqual(new byte[]{0xf0,0x70,0xfa,0x0f,0x8f,0xfa}),"DoP preserves temporal DSD bit order and channel assignment");check(frame[8]==0x05&&frame[11]==0x05,"DoP markers alternate together across channels");}
        using(var source=new NativeSource(new([new(Guid.NewGuid(),dsdTrack),new(Guid.NewGuid(),dsdTrack)]),new(Dsd:DsdMode.DoP))){source.Seek(4095);var frame=new byte[12];source.Read(frame,2,true);check(frame[2]==0xfa&&frame[8]==0x05,"DoP markers continue across physical file boundaries");}
        using(var control=new ScanControl()){control.Pause();using var cancel=new CancellationTokenSource();var waiting=Task.Run(()=>{try{control.Checkpoint(cancel.Token);return false;}catch(OperationCanceledException){return true;}});await Task.Delay(25);check(!waiting.IsCompleted,"Paused scan waits without continuing work");cancel.Cancel();check(await waiting,"Paused scan remains cancellable");}
        string tagFile=Path.Combine(root,"tag-edit-complete.wav");File.Copy(wav,tagFile,true);var editable=TrackOf(tagFile);var tagStore=new LibraryStore(Path.Combine(root,"tag-store-"+Guid.NewGuid().ToString("N")));tagStore.AddBatch([editable],fingerprints:new Dictionary<string,SourceFingerprint>{[tagFile]=LocalFileIdentity.Capture(tagFile)});var edit=TagEditing.Apply(editable,new("Edited","A;B","Album","Various","Jazz",2026,2,3),tagStore.AcceptTagEdit);check(File.Exists(edit.Backup)&&MetadataReader.Read(tagFile).Title=="Edited","Tag writer keeps complete original backup and writes WAV tags");check(tagStore.ReadAll()[0].Id==editable.Id&&tagStore.ReadAll()[0].Metadata?.Disc==2,"Intentional tag edits preserve library track identity");tagStore.ValidateSource(tagStore.ReadAll()[0]);check(true,"Intentional tag edits update source evidence");
        foreach(string extension in new[]{"mp3","m4a","alac.m4a","aiff","wv","ogg","opus"}){string path=Path.Combine(root,"extended."+extension);if(!File.Exists(path))throw new Exception("Missing generated codec fixture: "+path);var t=TrackOf(path);using var source=new NativeSource(new([new(Guid.NewGuid(),t)]),new());var all=new byte[checked((int)(source.Format.Frames*source.Format.Channels*source.Format.ContainerBits/8))];int frames=0;while(frames<source.Format.Frames){int n=(int)Math.Min(2048,source.Format.Frames-frames);var chunk=new byte[n*source.Format.Channels*source.Format.ContainerBits/8];int got=source.Read(chunk,n,true);chunk.CopyTo(all,frames*source.Format.Channels*source.Format.ContainerBits/8);frames+=got;}check(frames==t.TotalFrames,"Exact decoded duration: "+extension);long seek=Math.Min(1234,t.Frames-1);source.Seek(seek);var sample=new byte[source.Format.Channels*source.Format.ContainerBits/8];source.Read(sample,1,true);check(sample.SequenceEqual(all.Skip((int)seek*sample.Length).Take(sample.Length)),"Exact decoded seek: "+extension);}
    }
}
